// Keys that sanitise (`0` → `_0`, `$public` → `public`) must still address
// the original JS property from both the getter and the setter.
declare class Pair {
  constructor();
  0: Socket;
  1: Socket;
  static 2: Socket;
  $public: string;
  static "@cf/model": string;
}
declare class Socket {
  accept(): void;
}
